 auto scene=(project.parent_path()/"Scenes"/(name+".judas")).string();Application app;char binary[]="judas";char* args[]={binary,scene.data()};Check(app.Run(2,args,&control)==0&&complete,"ordinary application startup/shutdown");auto pct=[](std::vector<double> v,double p){std::sort(v.begin(),v.end());return v.empty()?0:v[size_t(p*(v.size()-1))];};std::printf("PERF fixed_p95_ms=%.6f fixed_max_ms=%.6f render_p95_ms=%.6f frame_p95_ms=%.6f frames=%zu\n",pct(physics,.95),pct(physics,1),pct(render,.95),pct(frames,.95),frames.size());std::printf("PERF interaction_fixed_p95_ms=%.6f interaction_fixed_max_ms=%.6f frames=%zu\n",pct(interaction,.95),pct(interaction,1),interaction.size());std::printf("SUMMARY case=%s mode=%s checks=%u failures=%u\n",name.c_str(),mode.c_str(),checks,failures);return failures?1:0;
